const ONG=[['Kontiki','An annual rafting weekend where patrols plan, build, sail and sleep on rafts.'],['Ventkhana, RallyVent and RoVent','Rally-style driving competitions that introduce newcomers to motorsport safely. Email motorsport@scoutswa.com.au.'],['Paddle nights','Paddling pool sessions at UWA on Thursday nights.'],['STEM and Innovation workshops','Free Special Interest Area workshops, including land radio and electronics. Email radio@scoutswa.com.au.'],['Survival Snippets','Short bushcraft and survival sessions at Manjedal, $10 each.'],['More on ScoutMap','Adventurous Activity and Program teams run activities nearly every week.']];
const evc=e=>`<div class="card"><p class="mute" style="margin:0 0 4px;font-weight:700">${e[1]}</p><h3>${e[0]}</h3><p class="mute" style="font-size:15px">${e[2]}</p><p>${e[3]}</p>${e[5]?`<a class="btn" href="${e[5]}" target="_blank" rel="noopener">${e[6]}</a>`:''}</div>`;
const V={
home(){return`<section class="hero"><img class="mark" src="${A.icon}" alt=""><div class="w"><h1>Scouts in Boulder</h1><p>Camping, hiking, friends and skills for life for young people aged 5 to 17. Come and try it free for three weeks.</p><a class="btn w2" href="join.html">Join Scouts</a><a class="btn ow" href="calendar.html">See what’s on</a></div></section>
<section class="w pull"><div class="g g4">${SK.map(secCard).join('')}</div></section>
<section class="w" style="padding-top:24px" id="live-home-gallery" aria-label="Approved Scout Group photos"></section>
<section class="sec w"><div class="g g2" style="gap:44px"><div><h2>Coming up</h2>${calendarStatus()}<div id="home-coming-up">${evl(upcomingEvents())}</div><p style="margin-top:18px"><a class="btn" href="calendar.html">Full calendar</a></p></div><div><h2>Latest news</h2>${newsList(4)}<p style="margin-top:18px"><a class="btn o" href="news.html">All news</a></p></div></div></section>
<section class="soft"><div class="w sec"><h2>How to get started</h2>${stp([['Pick a section','Choose the age group that fits.'],['Get in touch','Send us a message and we’ll find a night for you.'],['Try three weeks free','No uniform needed.'],['Register','Join through ScoutMap and collect your scarf.']])}</div></section>${join}`},
about(){return head('Our history','A Goldfields Scout tradition shaped by outdoor learning, community service and a much-loved hall. Dates are labelled according to the evidence available.')+`<section class="sec w history-page" style="padding-top:22px"><div class="history-intro"><p class="history-kicker"><span aria-hidden="true">✦</span> Boulder · Goldfields · Western Australia</p><h2>Adventure, service and a place to belong</h2><p>From early stories passed down through the group to milestones recorded in local news, Boulder Scouts’ history reflects practical skills, community service and a hall cared for by generations of members.</p><div class="history-highlights" aria-label="Selected history milestones"><div><strong>1908</strong><span>Group-supplied founding account</span></div><div><strong>2019</strong><span>Arboretum clean-up reported locally</span></div><div><strong>2024</strong><span>Historic hall reopening reported</span></div></div></div><details class="history-guide"><summary>How to read the history and source labels</summary><div class="history-guide-body"><p><span class="source-status verified">Published source</span> A public news report or official source supports the milestone described.</p><p><span class="source-status group">Group-supplied account</span> The story was supplied for this website, but the exact detail has not yet been corroborated by an accessible original record.</p><p>Where a source confirms only part of a story, the wording explains what is confirmed and what still needs an original record.</p></div></details><div class="timeline" aria-label="Boulder Scout Group historical timeline">
<div class="timeline-item"><div class="timeline-year">1908</div><div><span class="source-status group">Group-supplied account</span><h3>Foundation in the Goldfields</h3><p>The group’s historical account places Boulder Scout Group’s establishment in 1908, during the earliest years of Australian Scouting. It describes the group as giving local young people opportunities for outdoor adventure, practical skills and service. The exact Boulder founding date remains to be confirmed by an original local record.</p><div class="history-links">${historySourceLink('https://trove.nla.gov.au/newspaper/article/32517097','Trove archival research lead')}${historySourceLink('https://www.nationalredress.gov.au/institutions/boulder-scout-group','National Redress Scheme institution listing')}${historySourceLink('https://www.ckb.wa.gov.au/our-community/arts-culture-education/heritage-services-tours/local-history-archives.aspx','City archives for further verification')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">1944</div><div><span class="source-status group">Group-supplied account</span><h3>Community service during wartime</h3><p>The group’s account says the troop was asked to march and stand guard at the November 1944 funeral of Sophia Mabel Hopkins, following a request from the Acting District Commissioner. This specific funeral detail is awaiting confirmation from an original newspaper notice, troop record or funeral programme.</p><div class="history-links">${historySourceLink('https://trove.nla.gov.au/newspaper/article/32517097','Trove research starting point')}${historySourceLink('https://www.ckb.wa.gov.au/our-community/arts-culture-education/heritage-services-tours/local-history-archives.aspx','City archives for further verification')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">1946</div><div><span class="source-status group">Group-supplied account</span><h3>A hall made from a split aircraft hangar</h3><p>According to the group’s account, a former World War II aircraft hangar was divided into two sections after the war. One half reportedly went to Campbell Street for Kalgoorlie Scouts; the other became Boulder Scout Group’s hall on Hamilton Street. The engineering and transport story should be treated as oral history until a district, council or building record is located.</p><div class="history-links">${historySourceLink('https://www.ckb.wa.gov.au/our-community/arts-culture-education/heritage-services-tours/local-history-archives.aspx','City archives for further verification')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">2018</div><div><span class="source-status verified">Published source</span><h3>Local recognition for youth-service volunteering</h3><p>The Kalgoorlie-Boulder Volunteer Awards listed Brenda Clark of 1st Boulder Scout Group as the individual Youth category award recipient in December 2018. The report provides a published record of Scouting-related youth service being recognised in the local community.</p><div class="history-links">${historySourceLink('https://www.kalminer.com.au/news/kalgoorlie-miner/historian-and-food-charity-recognised-ng-b881045019z','Kalgoorlie Miner report · 10 December 2018')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">2019</div><div><span class="source-status verified">Published source</span><h3>Cubs care for the Kalgoorlie Arboretum</h3><p>Boulder Cub Scouts took part in a clean-up at the Kalgoorlie Arboretum, putting community service and care for the local environment into practice.</p><div class="history-links">${historySourceLink('https://www.kalminer.com.au/news/kalgoorlie-miner/boulder-cub-scouts-tidy-up-kalgoorlie-arboretum-ng-b881403679z','Kalgoorlie Miner report')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">2020</div><div><span class="source-status verified">Published source</span><h3>Keeping Scouting connected during COVID-19</h3><p>During pandemic restrictions, Boulder Scout Group continued connecting through Zoom catch-ups, helping the group stay prepared while normal in-person meetings were disrupted.</p><div class="history-links">${historySourceLink('https://www.kalminer.com.au/news/kalgoorlie-miner/boulder-scout-group-stays-prepared-with-zoom-catch-up-meetings-during-pandemic-ng-b881540623z','Kalgoorlie Miner report · 22 May 2020')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">2021–22</div><div><span class="source-status verified">Published source</span><h3>Speaking up for local community space</h3><p>The group publicly questioned a decision about the future use of a former public building behind the Scout hall, highlighting the importance of keeping community facilities available to local youth and not-for-profit groups.</p><div class="history-links">${historySourceLink('https://www.kalminer.com.au/news/kalgoorlie-miner/scouts-group-questions-decision-to-hand-old-building-to-social-society-c-4970725','Kalgoorlie Miner report')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">2022</div><div><span class="source-status verified">Published source</span><h3>Community support for lasting traditions</h3><p>The Rotary Club of Boulder contributed funding towards new section flags and signage, and helped with the cost of restumping the historic hall on Hamilton Street. The report records $2,500 for equipment/signage and $1,000 towards restumping support.</p><div class="history-links">${historySourceLink('https://www.kalminer.com.au/news/kalgoorlie-miner/rotary-club-of-boulder-donates-funds-to-continue-boulder-scouts-traditions-c-8040275','Kalgoorlie Miner report · 1 September 2022')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">2023</div><div><span class="source-status verified">Published source</span><h3>A $100,000 hall-restoration fundraising milestone</h3><p>Boulder Scout Group reached its reported $100,000 fundraising goal to help restump the ageing hall, a major step towards securing the building for future generations.</p><div class="history-links">${historySourceLink('https://www.kalminer.com.au/news/kalgoorlie-miner/boulder-scout-group-reaches-100000-fundraising-goal-to-restump-ageing-hall-c-12480948','Kalgoorlie Miner report')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">2024</div><div><span class="source-status verified">Published source</span><h3>Hall restoration and reopening</h3><p>The hall’s major restoration project culminated in a reopening celebrated by local Scout members and leaders. The group-supplied account describes a “Sponsor-a-Stump” campaign, 108 replacement stumps and six foundation beams, with the hall reopening on 23 June 2024; the exact construction quantities and date are retained as group-supplied details pending an original project report.</p><div class="history-links">${historySourceLink('https://www.kalminer.com.au/news/kalgoorlie-miner/boulder-scout-group-celebrates-much-anticipated-reopening-of-historic-hall-c-15108907','Kalgoorlie Miner hall reopening report')}</div><p><span class="source-status group">Group-supplied account</span> The group also reports that Boulder leaders helped mentor and relaunch Kalgoorlie Scout Group in February 2024 after a three-year pause, as local membership grew.</p></div></div>
<div class="timeline-item"><div class="timeline-year">2025</div><div><span class="source-status verified">Published source</span><h3>On the national stage at AJ2025</h3><p>The 26th Australian Scout Jamboree brought thousands of Scouts together in Queensland. Boulder’s account records a contingent of 10 youth and two leaders after local fundraising; those exact Boulder numbers remain group-supplied, while the national event itself is documented by Scouts Australia.</p><div class="history-links">${historySourceLink('https://scouts.com.au/blog/2025/02/26/aj2025-what-a-quest/','Scouts Australia · AJ2025')}</div></div></div>
<div class="timeline-item"><div class="timeline-year">2026</div><div><span class="source-status verified">Published source</span><h3>Recognition for service to young people</h3><p>Scouts Australia’s 2026 Adult Recognition Awards listing names Shane Treen as Assistant Scout Leader at Boulder Scout Group. The listing confirms his role in the group but does not specify the award level beside his name.</p><div class="history-links">${historySourceLink('https://scouts.com.au/blog/2026/07/28/scouts-australia-adult-recognition-awards-2026/','Scouts Australia · 2026 awards listing')}</div></div></div>
</div><p class="cal-note" style="margin-top:22px">History note: we welcome corrections, family records, photographs and copies of original documents. Please contact the group before adding personal details about children or living members.</p></section>
<section class="soft"><div class="w sec"><h2>What makes Boulder Scouts special?</h2><div class="g g3"><div><h3>Local roots</h3><p>Young people from Boulder and the wider Goldfields learn together and take part in community life.</p></div><div><h3>Hands-on learning</h3><p>Camping, teamwork, practical skills and service help young people grow in confidence.</p></div><div><h3>A hall for the future</h3><p>Community fundraising and restoration help preserve a home base for the next generation.</p></div></div></div></section>${join}`},
calendar(){return head('Group calendar','Confirmed events published in the Boulder Scout Group Google Calendars. Dates and times are shown in Australia/Perth; if a calendar has no published event, no placeholder is added.')+`<section class="sec w" style="padding-top:18px"><div class="g g2" style="margin-bottom:24px"><div><h2>Coming up</h2><p class="mute">This schedule updates from Google Calendar when the live calendar service is configured and calendars are public.</p>${calendarStatus().replace('cal-status','cal-status').replace('role=\"status\"','id=\"calendar-status\" role=\"status\"')}</div><div class="meetbox"><h3>Where events come from</h3><p>The group’s five Google Calendars are the source of truth. Leaders update events there; this page does not invent recurring meeting dates.</p><p class="cal-note">If you know events have been entered but none appear here, check the feed visibility and API connection. The links below open the original calendars.</p>${sourceCalendarLinks()}</div></div><div class="g g2" style="margin:18px 0 26px"><div class="card"><label for="ts">Select school term</label><select id="ts" aria-label="School term">${TERMS.map((t,i)=>`<option value="${i}">${t[0]}</option>`).join('')}</select></div><div class="card"><h3>Filter by section</h3><p class="mute">Show confirmed events for one section or all sections.</p><div class="chips" id="ch"></div></div></div><div id="el"></div><h2 style="margin-top:38px">Choose a section</h2><div class="g g4">${SK.map(k=>`<a class="card sc" style="--c:${S[k].c}" href="${pageHref(k)}"><img src="${A[k].em}" alt=""><h3>${S[k].n}</h3><small>Ages ${S[k].age}</small></a>`).join('')}</div></section>`},
news(){return head('News','The latest from all our sections.')+`<section class="sec w" style="padding-top:20px">${newsList(30)}</section>`},
join(){return head('Join Boulder Scouts','Scouts is open to everyone aged 5 to 17. The first three weeks are a free trial so you can see if it’s right for your family.')+`<section class="sec w" style="padding-top:24px">${stp([['Find a section','Pick the age group from the Sections menu.'],['Enquire','Send us a message. Leaders are volunteers, so allow a few days.'],['Free trial','Come along for three weeks. No uniform needed.'],['Register','Join through ScoutMap and pick up your scarf and badges.']])}<div class="g g2" style="margin-top:44px;gap:44px"><div><h2>What it costs</h2><p>Scouts WA charges an annual membership fee, and each group sets its own group fee. ${CFG.fee}</p><p>Financial help is available through the Scouts WA Caring Circle.</p><a class="btn" href="https://scoutswa.com.au/youth-program/" target="_blank" rel="noopener">Scouts WA fees and help</a></div><div><h2>Questions</h2><details open><summary>Do we need a uniform to start?</summary><p>No. Scarves and badges are provided by the group once you join.</p></details><details><summary>Can we visit before joining?</summary><p>Yes, through the free three-week trial. Get in touch to pick a night.</p></details><details><summary>How is my child kept safe?</summary><p>Scouts has a child safe framework with screening and strict safety measures. <a href="https://scouts.com.au/child-safe/" target="_blank" rel="noopener">Read more</a>.</p></details><details><summary>Can I volunteer?</summary><p>Yes, roles are flexible. Email recruitment@scoutswa.com.au or call (08) 6240 7700.</p></details><details><summary>What comes after Venturers?</summary><p>Rover Scouts (ages 18–25) and adult volunteer roles. <a href="https://scouts.com.au/join/rovers/" target="_blank" rel="noopener">Learn about Rovers</a>.</p></details></div></div></section>`},
resources(){return head('Resources','Official Scouting tools for families, young people and leaders.')+`<section class="sec w" style="padding-top:20px"><div class="tbl">${LINKS.map(l=>`<a href="${l[2]}" target="_blank" rel="noopener"><b>${l[0]}</b><span>${l[1]}</span></a>`).join('')}</div></section>`},
contact(){return head('Contact us','We’re volunteers, so please allow a few days for a reply.')+`<section class="sec w" style="padding-top:24px"><div class="g g2" style="gap:36px"><form id="fm"><div><label for="n">Your name</label><input id="n" name="n" required></div><div><label for="e">Email</label><input id="e" name="e" type="email" required></div><div><label for="s">About</label><select id="s" name="s">${SK.map(k=>`<option>${S[k].n} (ages ${S[k].age})</option>`).join('')}<option>Volunteering</option><option>Hall hire</option><option>Something else</option></select></div><div><label for="m">Message</label><textarea id="m" name="m" rows="5"></textarea></div><div><button class="btn">Send enquiry</button></div><p class="mute" style="font-size:15px">This opens your email app with the message ready to send to ${CFG.email}.</p></form><div>${contactBox()}</div></div></section>`},
events(){return head('State events','Branch events run all year, from camps and competitions to balls and training courses.')+`<section class="sec w" style="padding-top:20px"><div class="meetbox" style="margin-bottom:34px"><p><b>Registering:</b> use <a href="scoutmap.html">ScoutMap</a>. Closing dates are posted there and no late registrations can be accepted. For help email <a href="mailto:events@scoutswa.com.au">events@scoutswa.com.au</a> or phone (08) 6240 7700 and press 1.</p>${link('https://scoutmap.my.site.com/scouts/s/','Open ScoutMap')}${link('https://www.waventurers.com.au/events','Full state calendar')}</div><h2>Coming up</h2><div class="g g3">${EVS.filter(e=>e[4]&&e[4]>=today).sort((a,b)=>a[4]<b[4]?-1:1).map(evc).join('')||'<p class="mute">No dated upcoming events are listed here yet. Check the relevant event organiser for confirmed dates.</p>'}</div>${EVS.some(e=>!e[4])?`<h2 style="margin-top:38px">Dates not announced</h2><p class="mute">These state-wide opportunities have been mentioned, but no confirmed dates have been supplied. They are not listed as scheduled events.</p><div class="g g3">${EVS.filter(e=>!e[4]).map(evc).join('')}</div>`:''}<h2 style="margin-top:44px">All year round</h2><div class="g g3">${ONG.map(o=>`<div class="card"><h3>${o[0]}</h3><p>${o[1]}</p></div>`).join('')}</div>${EVS.some(e=>e[4]&&e[4]<today)?`<h2 style="margin-top:44px">Recent</h2><div class="g g3">${EVS.filter(e=>e[4]&&e[4]<today).map(evc).join('')}</div>`:''}</section>`},
training(){return head('Training','Venturers can build real skills and nationally recognised qualifications, for free. Learn by doing, online at your own pace, or at courses with other Venturers.')+`<section class="sec w" style="padding-top:20px"><div class="g g2">${[['Scouts OnDemand','Short online modules at your own pace. Log in with your member number from ScoutMap (More, then My Family Details). The Adventurous Activities streams help with Safe and Trained Participant courses and are good preparation for a risk assessment before a hike or camp.',['http://training.scouts.com.au/','Open Scouts OnDemand']],['SAIT certificates','The Scouts Australia Institute of Training offers Certificates II and III that build confidence and leadership, can count towards your WACE and strengthen your resume.',['https://scouts.com.au/members/sait/','About SAIT']],['Adventurous Activities','Safe and Trained Participant courses run from time to time. Check ScoutMap for dates, or contact an AA team through the Scouts WA directory. Venturers can join AA teams too.'],['Personal Development','Courses don’t have to be run by Scouts. Certificates from school, Cadets, SES, Surf Life Saving and other community groups can count towards your King’s Scout Award. Take them to your Unit Council and check the requirements on Terrain.',['http://terrain.scouts.com.au','Open Terrain']],['Unit Management','Courses run by Venturers, great for new Unit Councils and linking Scouts. Dates are on ScoutMap, and you can request a course for your group or district.'],['Scout Character Development','Course 3 is for Scouts and Venturers aged 14–16 and Course 4 is for Venturers and Rovers aged 16–20. A Unit, Group, District or Region can run one, and participants get free badges.'],['RST and Power Boat Operators','The skipper’s ticket course is open to all Scout members aged 14+, not just Sea Scouts, and usually runs over two weekends. Check ScoutMap for dates.'],['Turning 18?','There are required steps before your 18th birthday. Find the 18th Birthday Checklist on the Scouts WA general resources page.',['https://www.waventurers.com.au/training','Venturer training page']]].map(c=>`<div class="card"><h3>${c[0]}</h3><p>${c[1]}</p>${c[2]?link(c[2][0],c[2][1]):''}</div>`).join('')}</div></section>`},
scoutmap(){return head('ScoutMap guide','ScoutMap is where WA Venturers register for events and where organisers collect registrations, including unit nights away from the hall.')+`<section class="sec w" style="padding-top:20px"><h2>Registering</h2>${stp([['Log in','A parent or guardian logs in with their ScoutMap profile and can register you for any event.'],['Set up Authenticator','Parents need an authenticator app to log in securely.'],['Find the event','Open Events and Calendar. Choose Branch for state events, or Formation for region, district, group or unit events.'],['Register and pay','Click the reservation number beside the event. To pay later, log out on the payment page and find the invoice under More, then Invoices.']])}<p style="margin-top:18px">Register early. It helps organisers plan, and late registrations can’t be accepted.</p>${link('https://scoutmap.my.site.com/scouts/s/','Go to ScoutMap')}${link('https://www.waventurers.com.au/_files/ugd/3f2147_7e69b8f5a3e24ec09ff7311435e4f636.pdf','Authenticator cheat sheet')}${link('https://www.waventurers.com.au/_files/ugd/3f2147_30a74d724cc145eb962799664f865042.pdf','Parent Handbook')}<h2 style="margin-top:44px">Organising an event</h2>${stp([['Make a plan','Put your plan together and complete a risk assessment if needed.'],['Ask your leader','Your Adult Leader creates the event on ScoutMap.'],['Share it','Once it is created, share it with your unit.'],['After registration closes','Ask your leader for numbers, names and other details.']])}<p style="margin-top:18px">${link('https://www.waventurers.com.au/_files/ugd/3f2147_a343ce8bc184493696fbe21c29d0a4b1.pdf','Guide for Adult Leaders')}${link('https://www.waventurers.com.au/unitcouncil','Unit Council templates')}</p><div class="meetbox" style="margin-top:34px"><p><b>Need help?</b> Login problems: <a href="mailto:ict@scoutswa.com.au">ict@scoutswa.com.au</a>. Last-minute registrations: <a href="mailto:events@scoutswa.com.au">events@scoutswa.com.au</a> or (08) 6240 7700, press 1.</p></div></section>`}
,article(){const slug=new URLSearchParams(location.search).get('slug')||'';return head('News story','Full story from Boulder Scout Group.')+`<section class="sec w"><article id="article-content" class="card" data-slug="${escapeHTML(slug)}"><p class="mute">${CFG.apiBase?'Loading article…':'Article publishing is not connected yet. Please check back later.'}</p></article><p style="margin-top:18px"><a class="btn o" href="news.html">Back to news</a></p></section>`},
share(){return head('Share a photo or story','Help keep Boulder Scout Group’s history and activities alive. Every submission is reviewed before anything is published.')+`<section class="sec w"><div class="g g2" style="gap:34px"><div><form id="share-form" enctype="multipart/form-data"><div><label for="share-kind">What are you sharing?</label><select id="share-kind" name="kind" required><option value="photo">Photo(s)</option><option value="story">A story or group memory</option></select></div><div><label for="share-section">Section (for photos)</label><select id="share-section" name="section"><option value="joeys">Joey Scouts</option><option value="cubs">Cub Scouts</option><option value="scouts">Scouts</option><option value="venturers">Venturer Scouts</option></select></div><div><label for="share-title">Title</label><input id="share-title" name="title" maxlength="140" required></div><div><label for="share-story">Story or caption</label><textarea id="share-story" name="story" rows="5" maxlength="6000" placeholder="Add a caption, date, or story. For a photo this is optional."></textarea></div><div id="share-files-wrap"><label for="share-files">Photos (up to 5; JPEG, PNG or WebP; maximum 8 MB each)</label><input id="share-files" name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></div><div><label for="share-name">Your name</label><input id="share-name" name="submitterName" autocomplete="name" maxlength="120" required></div><div><label for="share-email">Your email (not shown publicly)</label><input id="share-email" name="submitterEmail" type="email" autocomplete="email" maxlength="254" required></div><div class="hp-field" aria-hidden="true"><label for="share-website">Leave this field blank</label><input id="share-website" name="website" tabindex="-1" autocomplete="off"></div><div><label><input type="checkbox" name="consent" value="yes" required> I confirm I have permission to share this content and understand it will be reviewed before publication.</label></div><div id="turnstile-slot"></div><button class="btn" type="submit" id="share-submit" disabled>Submit for review</button><p id="share-status" class="form-status" role="status" aria-live="polite">Submissions are paused until the site owner has configured the secure API and anti-spam protection. No submissions are sent from this page yet.</p></form></div><aside><div class="meetbox"><h2>Before you submit</h2><ul class="ul"><li>Do not upload photos or personal details unless you have permission.</li><li>Do not identify children publicly without appropriate parent/guardian consent.</li><li>Submissions are private and pending until an authorised admin approves them.</li><li>Submitter contact details are never displayed on public pages or in RSS feeds.</li></ul><p>For a general enquiry, email <a href="mailto:${CFG.email}">${CFG.email}</a>.</p></div></aside></div></section>`},
admin(){return head('Content review','Restricted to authorised Boulder Scout Group administrators.')+`<section class="sec w"><div id="admin-root"><div class="meetbox"><p><b>Private review area</b></p><p>Use the group’s admin password. Admin credentials are not stored in the site code; the session token is kept only for this browser tab/session.</p></div><form id="admin-login"><div><label for="admin-password">Admin password</label><input id="admin-password" name="password" type="password" autocomplete="current-password" required></div><button class="btn" type="submit" id="admin-login-button">Sign in</button><p class="form-help">${CFG.apiBase?'The login service will validate your password and apply server-side rate limiting.':'Admin features are unavailable until the Cloudflare API has been deployed and configured.'}</p><p id="admin-login-status" class="form-status" role="status" aria-live="polite"></p></form><div id="admin-queue" hidden></div></div></section>`},
privacy(){return head('Privacy and media permissions','How Boulder Scout Group handles website submissions and published content.')+`<section class="sec w"><div class="g g2"><div><h2>Photos and stories</h2><p>Content submitted through this website stays pending until an authorised administrator reviews it. Rejected content is removed from private media storage; only approved content is made public.</p><p>Only share content you have permission to provide. For images of children, follow Scouts WA child-safe guidance and obtain the appropriate parent/guardian permissions.</p></div><div><h2>Personal information</h2><p>Submitter email addresses and IP addresses are used for administration and abuse prevention, not displayed on the public website or in feeds. Do not put sensitive personal information in captions or stories.</p><p>Contact the group at <a href="mailto:${CFG.email}">${CFG.email}</a> to request a correction or removal.</p></div></div><h2 style="margin-top:36px">Calendar privacy</h2><p>The website reads public calendar feeds through its backend schedule endpoint. Only calendars the owner has made publicly readable can supply confirmed event details; private iCal subscription links must never be published.</p><h2 style="margin-top:36px">External services</h2><p>Google Calendar, Cloudflare Turnstile and the website’s hosting provider process requests according to their own terms and privacy notices. The website owner should review these settings and policies before activating online submissions.</p></section>`},
'404'(){return head('Page not found','That page may have moved or the link may be incorrect.')+`<section class="sec w"><p>Use the navigation above to find the section you need.</p><a class="btn" href="index.html">Back to the homepage</a></section>`}
};
const sec=k=>{const s=S[k],others=SK.filter(x=>x!==k);return`<section class="band"><img class="mark" src="${A.icon}" alt=""><div class="w"><img class="sl" src="${A[k].wh}" alt="${s.n}"><h1>${s.tag}</h1><p class="lead">${s.b}</p><a class="btn w2" href="contact.html">Join ${s.n}</a><a class="btn ow" href="calendar.html">Confirmed events</a></div></section>
<section class="sec w"><div class="g g2" style="gap:44px"><div><h2>What you’ll do</h2><ul class="ul">${s.do.map(d=>`<li>${d}</li>`).join('')}</ul><h3>Good to know</h3><p>${s.gear}</p>${link('https://resources.scouts.com.au/portal/en/home','Program resources')}</div><div class="meetbox"><dl><dt>Meeting place</dt><dd>${CFG.hall}<br>${CFG.addr}</dd><dt>Ages</dt><dd>${s.age} years</dd><dt>Contact</dt><dd><a href="mailto:${CFG.email}">${CFG.email}</a></dd></dl><p class="cal-note">Upcoming dates below appear only when an event is published in the group calendars. No recurring dates are assumed. If you can see an event in Google Calendar but not here, the site calendar service may not yet have permission to read that calendar.</p>${sourceCalendarLinks(k)}<p style="margin:18px 0 0"><a class="btn" href="contact.html">Try three weeks free</a></p></div></div></section>
<section class="soft"><div class="w sec"><h2>Coming up for ${s.n}</h2>${calendarStatus()}<div id="section-coming-up-${k}">${evl(upcomingEvents(k))}</div><p style="margin-top:18px"><a class="btn" href="calendar.html">Whole calendar</a></p></div></section>
<section class="w" id="live-section-gallery-${k}" aria-label="${s.n} photo album"></section>
${k==='venturers'?`<section class="soft venturer-social"><div class="w sec"><div class="social-title-row"><div><p class="eyebrow">From our unit</p><h2>Venturers on Instagram</h2><p class="lead">A look at the adventures, projects and people behind Boulder Venturers.</p></div><a class="btn" href="https://www.instagram.com/boulder_venturers/" target="_blank" rel="noopener noreferrer">Follow the unit ↗</a></div><div class="instagram-frame"><blockquote class="instagram-media" data-instgrm-permalink="https://www.instagram.com/boulder_venturers/" data-instgrm-version="14" aria-label="Boulder Venturers Instagram profile"><p><a href="https://www.instagram.com/boulder_venturers/" target="_blank" rel="noopener noreferrer">View @boulder_venturers on Instagram</a></p></blockquote></div><p class="form-help">Instagram content is supplied by Instagram and may take a moment to load. The link above still works if embeds are disabled by the account or browser.</p></div></section><section class="sec w"><h2>Venturers across Western Australia</h2><p class="lead">Our Venturers are part of a state-wide community with its own events, training and awards, run by Venturer Scouts WA.</p><div class="g g4" style="margin:26px 0">${SIA.map(a=>`<div class="sia"><i><img src="${a[1]}" alt=""></i><div><b style="font:700 1.2rem var(--h)">${a[0]}</b><br><span class="mute" style="font-size:15px">${a[2]}</span></div></div>`).join('')}</div><div class="g g2" style="gap:44px"><div><h3>The King’s Scout Award</h3><p>The highest award in the Venturer section. Venturers complete the Venturer Award activities, then reach King’s Scout standard across leadership, outdoors, personal growth and community involvement.</p></div><div><h3>Venturer Scouts WA</h3>${link('https://www.waventurers.com.au/','Venturer Scouts WA website')}<br>${link('https://www.facebook.com/VenturersWA/','Facebook')}<br><a class="lk" href="events.html">State events</a><a class="lk" href="training.html">Training</a><a class="lk" href="scoutmap.html">ScoutMap guide</a><br><a class="lk" href="mailto:bvc@scoutswa.com.au">Venturer Council: bvc@scoutswa.com.au</a></div></div></section>`:''}
<section class="${k==='venturers'?'soft':''}"><div class="w sec"><h2>Other sections</h2><div class="g g4">${others.map(secCard).join('')}</div></div></section>${join}`};
SK.forEach(k=>V[k]=()=>sec(k));
function refreshAfterData(kind){
 const file=(location.pathname.split('/').pop()||'index.html').toLowerCase();
 const pathRoute=file==='index.html'||file===''?'home':file.replace(/\.html?$/,'');
 let active=location.hash.slice(1);if(!V[active])active=document.body.dataset.page||pathRoute||'home';
 const calendarViews=['home','calendar','joeys','cubs','scouts','venturers'];
 const newsViews=['home','news'];
 if((kind==='calendar'&&calendarViews.includes(active))||(kind==='news'&&newsViews.includes(active)))route();
}
function drawCal(){const t=TERMS[ti];$('#ts').value=ti;$('#ts').onchange=e=>{ti=+e.target.value;drawCal()};$('#ch').innerHTML=['all',...SK].map(k=>`<button type="button" class="chip${k===cf?' on':''}" data-k="${k}">${S[k]?S[k].n:'All sections'}</button>`).join('');$('#ch').onclick=e=>{const b=e.target.closest('[data-k]');if(b){cf=b.dataset.k;drawCal()}};const status=$('#calendar-status');if(status)status.outerHTML=calendarStatus().replace('cal-status','cal-status').replace('role="status"','id="calendar-status" role="status"');$('#el').innerHTML=`<h2>${t[0]}</h2>`+evl(inTerm(t,cf==='all'?null:cf))}
let instagramEmbedLoader=null;
function mountInstagramProfile(page){if(page!=='venturers')return;const profile=document.querySelector('.instagram-media');if(!profile)return;const process=()=>{try{if(window.instgrm&&window.instgrm.Embeds)window.instgrm.Embeds.process()}catch(e){console.info('Instagram embed is unavailable; profile link remains available.')}};if(window.instgrm&&window.instgrm.Embeds){process();return}if(!instagramEmbedLoader){instagramEmbedLoader=document.createElement('script');instagramEmbedLoader.src='https://www.instagram.com/embed.js';instagramEmbedLoader.async=true;instagramEmbedLoader.onload=process;instagramEmbedLoader.onerror=()=>console.info('Instagram embed could not load; profile link remains available.');document.head.appendChild(instagramEmbedLoader)}else instagramEmbedLoader.addEventListener('load',process,{once:true})}
let routeAnimationFrame=0;
function animatePageContent(){if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const app=document.getElementById('app');if(!app)return;app.classList.remove('page-arrive');void app.offsetWidth;app.classList.add('page-arrive');clearTimeout(routeAnimationFrame);routeAnimationFrame=setTimeout(()=>app.classList.remove('page-arrive'),650)}
function route(){const file=(location.pathname.split('/').pop()||'index.html').toLowerCase();const pathRoute=file==='index.html'||file===''?'home':file.replace(/\.html?$/,'');let r=location.hash.slice(1);if(!V[r])r=(document.body.dataset.page||pathRoute||'home');if(!V[r])r='404';const s=S[r],rt=document.documentElement.style;ti=curTerm();rt.setProperty('--accent',s?s.c:'#800000');rt.setProperty('--deep',s?s.d:'#800000');let html=V[r]();html=html.replace(/href="#(home|about|joeys|cubs|scouts|venturers|calendar|news|article|share|admin|join|contact|resources|events|training|scoutmap|privacy|404)"/g,(m,key)=>`href="${pageHref(key)}"`);$('#app').innerHTML=html;navState(r);mountInstagramProfile(r);animatePageContent();document.title=(s?s.n:(L[r]||({article:'News story',share:'Share a photo or story',admin:'Content review',privacy:'Privacy',404:'Page not found'}[r])||'Boulder Scouts'))+' | Boulder Scouts';if(r==='calendar')drawCal();const f=$('#fm');if(f)f.onsubmit=e=>{e.preventDefault();const d=new FormData(f);location.href='mailto:'+CFG.email+'?subject='+encodeURIComponent('Enquiry: '+d.get('s'))+'&body='+encodeURIComponent(d.get('m')+'\\n\\n'+d.get('n')+' ('+d.get('e')+')')};if(window.BoulderSiteModules){for(const hook of (window.BoulderSiteModules.routeHooks||[])){try{hook(r)}catch(err){console.warn('A Boulder Scouts page module could not refresh.',err)}}if(typeof window.BoulderSiteModules.onRoute==='function')window.BoulderSiteModules.onRoute(r)}}
addEventListener('hashchange',()=>{route();scrollTo(0,0)});ti=curTerm();route();loadICS();loadFeed();
